-- 2026-10-20 지원 전 체크 › 자주 묻는 질문(FAQ)을 DB 표로 옮긴다(표 6개 → 7개). 관리자 '지원 전 Check FAQ 관리'가 이 표를 고치고,
-- 사이트는 공개 API(/api/public/faq.js)로 받아 그린다. 백오피스가 꺼져 있을 때를 위해 같은 내용을 사본(check/js/faq-data.js)으로도 쓴다.
-- 처음 질문 21개는 사용자가 정리해 준 표(번호 · 분류 · 질문 · 답변) 그대로다. 답은 사이트에 있던 링크 · 강조 표시를 살린 HTML.
CREATE TABLE faqs (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    category    VARCHAR(30)  NOT NULL,                 -- 분류: 사이트 분류 버튼(data-cat) 이름(준비사항 · 수업 · 생활 · 지원금 · 프로젝트)
    question    VARCHAR(400) NOT NULL,                 -- 질문
    answer      TEXT         NOT NULL,                 -- 답변(HTML: 링크 · 굵게 · 기울임 · 강조 · 줄바꿈 · '확인 필요' 표시만)
    sort_order  INT          NOT NULL,                 -- 번호(사이트에 보이는 순서)
    created_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX ix_faqs_order ON faqs (sort_order);

